use std::fs

fn prec(op: string) -> int {
    if op == "^" { return 3 }
    if op == "*" || op == "/" { return 2 }
    if op == "+" || op == "-" { return 1 }
    0
}

fn convert(line: string) -> string {
    let mut toks: Vec<string> = []
    let mut cur = ""
    for c in line.chars() {
        if c.is_ascii_digit() {
            cur = cur + c.to_string()
        } else {
            if cur != "" {
                toks.push(cur)
                cur = ""
            }
            if c == ' ' || c == '\t' || c == '\r' {
            } else if c == '+' || c == '-' || c == '*' || c == '/' || c == '^' || c == '(' || c == ')' {
                toks.push(c.to_string())
            } else {
                return "error"
            }
        }
    }
    if cur != "" {
        toks.push(cur)
    }
    let mut out: Vec<string> = []
    let mut stack: Vec<string> = []
    let mut expect = true
    for t in toks {
        let p = prec(t)
        if t == "(" {
            if !expect { return "error" }
            stack.push(t)
        } else if t == ")" {
            if expect { return "error" }
            let mut found = false
            while stack.len() > 0 {
                let top = stack.pop().unwrap_or("")
                if top == "(" {
                    found = true
                    break
                }
                out.push(top)
            }
            if !found { return "error" }
        } else if p > 0 {
            if expect { return "error" }
            while stack.len() > 0 {
                let top = stack[stack.len() - 1]
                let tp = prec(top)
                if tp > p || (tp == p && t != "^") {
                    out.push(stack.pop().unwrap_or(""))
                } else {
                    break
                }
            }
            stack.push(t)
            expect = true
        } else {
            if !expect { return "error" }
            out.push(t)
            expect = false
        }
    }
    if expect { return "error" }
    while stack.len() > 0 {
        let top = stack.pop().unwrap_or("")
        if top == "(" { return "error" }
        out.push(top)
    }
    out.join(" ")
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" { continue }
        println(convert(line))
    }
}

